"""Frozen human-authored evaluation cases. Not generated by the ranker."""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any


@dataclass(frozen=True)
class EvalCase:
    id: str
    query: str
    gold_constraint_fields: set[str]
    gold_contexts: set[str] = field(default_factory=set)
    gold_outcomes: set[str] = field(default_factory=set)
    gold_preferences: set[str] = field(default_factory=set)
    gold_tradeoffs: set[str] = field(default_factory=set)
    relevance: dict[str, Any] = field(default_factory=dict)
    notes: str = ""


def _c(
    cid: str,
    query: str,
    *,
    fields: set[str],
    contexts: set[str] | None = None,
    outcomes: set[str] | None = None,
    prefs: set[str] | None = None,
    tradeoffs: set[str] | None = None,
    relevance: dict[str, Any] | None = None,
    notes: str = "",
) -> EvalCase:
    return EvalCase(
        id=cid,
        query=query,
        gold_constraint_fields=fields,
        gold_contexts=contexts or set(),
        gold_outcomes=outcomes or set(),
        gold_preferences=prefs or set(),
        gold_tradeoffs=tradeoffs or set(),
        relevance=relevance or {},
        notes=notes,
    )


