def _extra_case(row: tuple[str, str, set[str], dict[str, Any]]) -> EvalCase:
    cid, query, fields, relevance = row
    contexts: set[str] = set()
    outcomes: set[str] = set()
    prefs: set[str] = set()
    lowered = query.lower()
    if "flight" in lowered or "sydney" in lowered or "travel" in lowered:
        contexts.add("long_haul_travel")
    if "hours" in lowered:
        contexts.add("extended_continuous_use")
        outcomes.add("low_fatigue")
    if "comfort" in lowered:
        prefs.add("comfort")
    if "office" in lowered:
        contexts.add("office")
    if "gaming" in lowered:
        contexts.add("gaming")
    if "studio" in lowered:
        contexts.add("studio")
    if "gym" in lowered or "running" in lowered:
        contexts.add("sports")
    if "commut" in lowered:
        contexts.add("commuting")
    if "frequent" in lowered:
        contexts.add("frequent_travel")
    return _c(
        cid,
        query,
        fields=fields,
        contexts=contexts,
        outcomes=outcomes,
        prefs=prefs,
        relevance=relevance,
    )


EVAL_CASES = [*EVAL_CASES, *[_extra_case(row) for row in _EXTRA_QUERIES]]
